WFJ.Data.add("spell", {
  [1218038] = { "In catene di ghiaccio finché i ceppi non vengono distrutti.", "In catene di ghiaccio finché i ceppi non vengono distrutti.", 0xcbb3f329, 0xcbb3f329, "uu" },
  [1218071] = { "Evoca un fiorcanto che conferisce a tutti i membri del tuo gruppo o della tua incursione un aumento del $N1% della probabilità di critico in mischia, a distanza o magico e di $N2 a tutte le caratteristiche per $D1. Non si somma ad altri effetti globali simili. Non è influenzato dai Chronoboon.", "Aumenta la probabilità di critico in mischia, a distanza o magico del $N1% e tutte le caratteristiche di $N2.", 0xe9db065f, 0x1e139466, "uu" },
  [1218072] = { "Conferisce a tutti i membri del tuo gruppo o della tua incursione vicini un aumento di $N1 della potenza d'attacco, del $N2% della Tempra e del $N3% della probabilità di critico magico per $D1. Non si somma ad altri effetti globali simili. Non è influenzato dai Chronoboon.", "Aumenta la potenza d'attacco di $N1, la Tempra del $N2% e la probabilità di critico magico del $N3%.", 0xa55ec68e, 0x23a55955, "uu" },
  [1218073] = { "Conferisce a tutti i membri del tuo gruppo o della tua incursione un aumento del $N1% dei danni inflitti per $D1.", "Aumenta i danni del $N1%.", 0x4b878a31, 0x416dea0f, "uu" },
  [1218074] = { "Aumenta la salute di $N1. Velocità degli attacchi in mischia aumentata del $N2%. Rigenera $N3 mana ogni $N4 s. Dura $D1.", "Aumenta la salute di $N1. Velocità degli attacchi in mischia aumentata del $N2%. Rigenera $N3 mana ogni $N4 s.", 0xd8f57e36, 0xc53fc1df, "uu" },
  [1218075] = { "Conferisce a tutti i membri del tuo gruppo o della tua incursione un aumento del $N1% della velocità di movimento e del $N2% delle caratteristiche per $D1.", "Aumenta la velocità di movimento del $N1% e tutte le caratteristiche del $N2%.", 0x93e448ff, 0x0d29e698, "uu" },
  [1218121] = { "Raduna i membri del gruppo o dell'incursione vicini, conferendo loro un aumento del $N1% della probabilità di critico magico, del $N2% della probabilità di critico in mischia e a distanza e di $N3 della potenza d'attacco. Dura $D1. Non si somma ad altri effetti globali simili e non è influenzato dai Chronoboon.", "Aumenta la probabilità di critico degli incantesimi del $N1%, in mischia e a distanza del $N2% e conferisce $N3 potenza d'attacco.", 0xe487cf6e, 0x04d1ed33, "uu" },
  [1218134] = { "Tenta di rimuovere $N1 effetto di Frenesia da una creatura nemica.", nil, 0x19756a13, nil, "um" },
  [1218154] = { nil, "⟦Sinister Strike=Assalto Funesto⟧ colpisce $N1 bersaglio aggiuntivo vicino.", nil, 0xb2d18ca2, "mu" },
  [1218198] = { "L'Arachnid Quarter è potenziato. Durante il combattimento, nelle vicinanze compaiono a caso delle sacche di uova che esplodono dopo alcuni secondi.", "L'Arachnid Quarter è potenziato. Durante il combattimento, nelle vicinanze compaiono a caso delle sacche di uova che esplodono dopo alcuni secondi.", 0xd438ca64, 0xd438ca64, "uu" },
  [1218216] = { "Infligge danni da natura nel tempo. Conferisce ai tuoi attacchi una probabilità di generare servitori ragno che si lanciano contro i tuoi nemici.", "Infligge danni da natura nel tempo. Conferisce ai tuoi attacchi una probabilità di generare servitori ragno che si lanciano contro i tuoi nemici.", 0xa195c5d5, 0xa195c5d5, "uu" },
  [1218240] = { "Tenti di finire un bersaglio ferito con un attacco a distanza che infligge il $N1% dei danni dell'arma più $N2. Tiro Mortale non ha una portata minima. Il tempo di recupero di Tiro Mortale si azzera se viene usato su un nemico con il $N3% di salute o meno.", nil, 0xeae59b96, nil, "um" },
  [1218271] = { "Le forze del Flagello si rafforzano.", "Le forze del Flagello si rafforzano. Probabilità di schivata ridotta del $N1% e probabilità di subire colpi aumentata del $N2%.\n\nI benefici del tuo ⟦Seal of the Dawn=Sigillo dell'Alba⟧ non possono superare il Grado $N3.", 0xc72f3794, 0x23ad32b4, "uu" },
  [1218275] = { "Le forze del Flagello si rafforzano.", "Le forze del Flagello si rafforzano. Probabilità di schivata ridotta del $N1% e probabilità di subire colpi aumentata del $N2%.\n\nI benefici del tuo ⟦Seal of the Dawn=Sigillo dell'Alba⟧ non possono superare il Grado $N3.", 0xc72f3794, 0xe33d2031, "uu" },
  [1218276] = { "Le forze del Flagello si rafforzano.", "Le forze del Flagello si rafforzano. Probabilità di schivata ridotta del $N1% e probabilità di subire colpi aumentata del $N2%.\n\nI benefici del tuo ⟦Seal of the Dawn=Sigillo dell'Alba⟧ non possono superare il Grado $N3.", 0xc72f3794, 0xe33d2031, "uu" },
  [1218283] = { "Il Re dei Lich in persona se n'è accorto. Qui non resta alcuna speranza.", "Il Re dei Lich in persona se n'è accorto. Qui non resta alcuna speranza. Probabilità di schivata ridotta del $N1% e probabilità di subire colpi aumentata del $N2%.\n\nI benefici del tuo ⟦Seal of the Dawn=Sigillo dell'Alba⟧ non possono superare il Grado $N3.", 0xa62b4834, 0xdcc174e4, "uu" },
  [1218285] = { nil, "Non puoi beneficiare dell'effetto Pronto al Tiro.", nil, 0xfaeb76d0, "mu" },
  [1218345] = { nil, "Il bersaglio subisce il $N1% di danni in più dalla prossima Lancia di Ghiaccio dell'incantatore.", nil, 0xea71cd63, "mu" },
  [1218352] = { "Conferisce ai tuoi incantesimi di danno da gelo il $N1% di probabilità di applicare l'effetto Gelo Invernale, che aumenta del $N2% per $D1 la probabilità che un incantesimo di gelo infligga un colpo critico al bersaglio. Si accumula fino a $N4 volte.", nil, 0x5d65740f, nil, "um" },
  [1218358] = { "Fa cadere il bersaglio in una frenesia rabbiosa, aumentandone la potenza d'attacco in mischia di $N1 ma riducendone l'Armatura di $N2 per $D1. I nemici rabbiosi non fuggono e ignorano gli effetti di paura e orrore.", "Aumenta la potenza d'attacco in mischia di $N1 e riduce l'Armatura di $N2. Il bersaglio non fugge e ignora gli effetti di paura e orrore.", 0xadcaaf07, 0x83fba197, "uu" },
  [1218363] = { "Punisce un nemico, infliggendo danni da sacro.", nil, 0x20941603, nil, "um" },
  [1218364] = { "Punisce un nemico, infliggendo danni da sacro.", nil, 0x20941603, nil, "um" },
  [1218366] = { "Un'oscurità magica e gelida ti avvolge...", "Un'oscurità magica e gelida ti avvolge...", 0x99e047cf, 0x99e047cf, "uu" },
  [1218367] = { "Solleva l'Enchanted Torch e tenta di dissipare l'oscurità vicino alle Karazhan Crypts.", nil, 0xc5218775, nil, "um" },
  [1218423] = { "Il tuo Bocciolo di Vita ha ora il $N1% di probabilità di curare il bersaglio quanto un'applicazione della cura che fornisce quando viene dissolto, ogni volta che il bersaglio subisce danni. Questo effetto può verificarsi solo una volta ogni pochi secondi.", nil, 0x1848efd0, nil, "um" },
  [1218427] = { "Ogni volta che il tuo Rinvigorimento di grado $N1 o di grado $N2 cura un bersaglio, hai il $N3% di probabilità di ripristinare al bersaglio $N4 mana, $N5 energia o $N6 rabbia.", nil, 0xd90deaa1, nil, "um" },
  [1218429] = { "Il tuo Rinvigorimento e la tua Ricrescita riportano la loro durata al massimo ogni volta che il loro bersaglio subisce danni da un nemico Non Morto.", nil, 0x1907f36e, nil, "um" },
  [1218443] = { "Il tuo Fuoco Lunare e il tuo Fuoco Solare infliggono il $N1% di danni in più.", nil, 0x4762831c, nil, "um" },
  [1218444] = { "Riduce di $D1 il tempo di recupero del tuo incantesimo Cometa Arcana.", nil, 0xa034b581, nil, "um" },
  [1218445] = { "Quando la tua Cometa Arcana colpisce un bersaglio Non Morto, la durata residua della tua Pioggia di Stelle attiva viene riportata a $D1.", nil, 0xa0e20048, nil, "um" },
  [1218476] = { "Il tuo Graffio infligge ora i suoi danni periodici ogni $D1, aumentando del $N2% i suoi danni totali nel tempo.", nil, 0x77191e7b, nil, "um" },
  [1218477] = { "Riduce del $N1% il tempo di recupero della tua ⟦Tiger's Fury=Furia della Tigre⟧.", nil, 0x4db15c39, nil, "um" },
  [1218478] = { "Ogni volta che infliggi danni da sanguinamento a un bersaglio Non Morto, i tuoi danni e i tuoi danni critici inflitti ai Non Morti aumentano del $N1% per $D1, fino a un massimo di $N3 accumuli.", nil, 0x4064eb1d, nil, "um" },
  [1218479] = { nil, "Danni e danni critici inflitti ai Non Morti aumentati del $N1%.", nil, 0xd6f5d105, "mu" },
  [1218482] = { "La tua abilità Ringhio non manca mai il bersaglio, e la probabilità che i tuoi attacchi vengano schivati o parati è ridotta del $N1%.", nil, 0x5bc5577f, nil, "um" },
  [1218485] = { "Aumenta del $N1% tutti i danni inflitti ai bersagli di ⟦Silithus=Silitus⟧, ⟦Ahn'Qiraj=Ahn'qiraj⟧, delle ⟦Eastern Plaguelands=Terre Infette Orientali⟧ e di Naxxramas e aumenta di un ulteriore $N2% i danni critici inflitti ai bersagli in queste zone.", "Danni contro i bersagli di ⟦Silithus=Silitus⟧, ⟦Ahn'Qiraj=Ahn'qiraj⟧, delle ⟦Eastern Plaguelands=Terre Infette Orientali⟧ e di Naxxramas aumentati del $N1%.\nAnche i danni critici contro i bersagli in queste zone sono aumentati del $N2%.", 0x4212319f, 0xf06a2af8, "uu" },
  [1218506] = { "Costringe il bersaglio ad attaccarti, ma non ha effetto se il bersaglio ti sta già attaccando.", nil, 0x71de38fd, nil, "um" },
  [1218507] = { "Riduce di $D1 il tempo di recupero del tuo Istinto di Sopravvivenza e di $D2 il tempo di recupero della tua abilità Berserk.", nil, 0xba096367, nil, "um" },
  [1218509] = { "Quando subisci danni da un nemico Non Morto, la durata residua della tua ⟦Frenzied Regeneration=Rigenerazione Furiosa⟧ attiva viene riportata a $D1. Inoltre, ⟦Frenzied Regeneration=Rigenerazione Furiosa⟧ non consuma mai gli ultimi $N2 punti di rabbia per generare cure.", nil, 0x4f329ae2, nil, "um" },
  [1218514] = { "Il tuo Morso del Serpente infligge il $N1% di danni in più.", nil, 0xfa192432, nil, "um" },
  [1218515] = { "Riduce di $D1 il tempo di recupero di Tiro della Chimera, ⟦Explosive Shot=Tiro Esplosivo⟧ e ⟦Aimed Shot=Tiro Mirato⟧, di $D2 quello di Tiro Mortale e di $D3 quello di Tiro Multiplo.", nil, 0xc2378285, nil, "um" },
  [1218575] = { "Ogni volta che colpisci un nemico Non Morto con un attacco a distanza, i tuoi danni e i tuoi danni critici inflitti ai Non Morti aumentano del $N1% per $D1, fino a un massimo di $N3 accumuli.", nil, 0x12458615, nil, "um" },
  [1218582] = { "Wyvern Strike e Morso della Mangusta infliggono il $N1% di danni iniziali in più.", nil, 0x164f838f, nil, "um" },
  [1218583] = { "Riduce di $D1 il tempo di recupero della tua abilità Wyvern Strike, di $D2 quello della tua abilità Assalto del Raptor e di $D3 quello della tua abilità Assalto Fiancheggiato.", nil, 0xe343e3b8, nil, "um" },
  [1218587] = { nil, "Danni e danni critici inflitti ai Non Morti aumentati del $N1%.", nil, 0xd6f5d105, "mu" },
  [1218589] = { "Ogni volta che colpisci un nemico Non Morto con un attacco in mischia, i tuoi danni e i tuoi danni critici inflitti ai Non Morti aumentano del $N1% per $D1, fino a un massimo di $N3 accumuli. Gli accumuli si perdono quando esegui un attacco a distanza.", nil, 0x02ea5910, nil, "um" },
  [1218592] = { "Gli alleati con il tuo Temporal Beacon recuperano $N1 salute ogni $D1.", nil, 0x8cc45e42, nil, "um" },
  [1218693] = { "La tua abilità Rigenerazione conferisce al bersaglio un aumento del $N1% della velocità di movimento mentre la canalizzi, e ogni volta che cura il bersaglio, questo ha una probabilità di ottenere un aumento del $N2% della velocità d'attacco e di lancio per $D1.", nil, 0x26c1a19a, nil, "um" },
  [1218695] = { nil, "Velocità d'attacco e di lancio aumentate del $N1%.", nil, 0xd3c81828, "mu" },
  [1218697] = { "I danni che infliggi ai Non Morti generano il $N1% di cure cronomantiche in più, e ottieni mana pari al $N2% delle cure cronomantiche che generi danneggiando i Non Morti.", nil, 0x326c1470, nil, "um" },
  [1218700] = { { "La tua Evocazione ti conferisce un aumento del $N1% dei danni inflitti per ogni secondo di canalizzazione, accumulabile fino a $N2 volte e con una durata di $D1.", shape = { "3/1" } }, nil, 0xe9850268, nil, "um" },
  [1218701] = { nil, "Tutti i danni inflitti aumentati del $N1%.", nil, 0x87211d4f, "mu" },
